const seen = new Set();
return $input.all().map((item) => {
 const event = item.json || {};
 const eventId = String(event.eventId ?? '').trim();
 const email = String(event.email ?? '').trim().toLowerCase();
 const name = String(event.name ?? '').trim();
 const isEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
 let status = 'ready';
 let reason = 'Validated synthetic record';
 if (!eventId || !isEmail || !name) {
   status = 'invalid'; reason = 'Missing eventId/name or invalid email';
 } else if (seen.has(eventId)) {
   status = 'duplicate'; reason = 'Duplicate eventId in this execution';
 }
 if (eventId) seen.add(eventId);
 return {json:{eventId,email,name,source:String(event.source ?? 'unknown'),status,reason}};
});

